\begin{itemize}[leftmargin=1.5cm, topsep=1pt, itemsep=1pt]
  \item Vẽ đoạn thẳng $AB = 3\text{ cm}$.
  \item Dùng compa vẽ cung tròn tâm $A$ bán kính $3\text{ cm}$ và cung tròn tâm $B$ bán kính $3\text{ cm}$.
  \item Hai cung tròn cắt nhau tại điểm $C$.
  \item Nối $C$ với $A$ và $B$, ta được tam giác đều $ABC$ cạnh $3\text{ cm}$.
\end{itemize}
